-- SUPERSEDED by supabase/migrations/0060_rls_initplan.sql (generated by scripts/rls-initplan.ts, proven by
-- tests/rls-initplan-equivalence.test.ts). Nothing runs this file any more; it is kept as the record of the experiment the migration
-- came from. Differences: the migration spells out one `alter policy` per policy instead of this regular expression, also rewrites
-- organizations_select (`app.can_access_org(id)`, which this file's pattern missed), and deduplicates the candidates with UNION.
--
-- PROPOSAL, NOT A MIGRATION. The performance suite applied this to its throwaway in-memory database only (phase "proposed-rls"), to measure
-- what it would change. Adopting it needs its own reviewed migration and the full tenant-isolation suite. See docs/crm-performance.md.
--
-- Why: every member read runs under row-level security, and the policies call app.has_permission(org_id, '<permission>') (or
-- app.can_view_conversation / app.can_access_org) with the row's org_id. Those are SECURITY DEFINER SQL functions, so PostgreSQL cannot
-- inline them and calls them once per row it reads: a count over 50,000 contacts makes 50,000 calls, each running several lookups. In the
-- performance suite that per-row cost is most of the time of every list, count, search, report and inbox read.
--
-- What: two helpers return, once per statement, the set of organizations where the current user holds a permission (or has access at all).
-- Each policy's per-row call is rewritten mechanically to `org_id = ANY ((SELECT app.permitted_orgs('<permission>'))::uuid[])`; the sub-select is an
-- InitPlan, evaluated once per statement, and the comparison is a plain leakproof uuid test the planner can also use as an index condition.
--
-- Equivalence: has_permission(X, p) can only be true when the user is a member of X (org_role is not null), or staff_assigned(X) holds (an
-- agency super admin: every organization; agency staff: their staff_assignments). permitted_orgs takes exactly those candidates and keeps
-- the ones where has_permission(X, p) is true, so `X = ANY (permitted_orgs(p))` is true exactly when has_permission(X, p) is. Both are
-- STABLE and see the statement's snapshot. can_view_conversation and can_access_org are expanded the same way from their definitions.
-- Only SELECT policies are rewritten (members never write directly; writes run as trusted code).

create or replace function app.permitted_orgs(p_permission text) returns uuid[]
language sql stable security definer set search_path = public, pg_temp
as $$
  select coalesce(array_agg(distinct c.org_id), '{}'::uuid[])
  from (
    select m.org_id from organization_memberships m where m.user_id = app.current_user_id()
    union all
    select s.org_id from staff_assignments s where s.user_id = app.current_user_id()
    union all
    select o.id from organizations o where app.is_agency_admin()
  ) c
  where app.has_permission(c.org_id, p_permission)
$$;
revoke all on function app.permitted_orgs(text) from public;
grant execute on function app.permitted_orgs(text) to iaq_app_user;

create or replace function app.accessible_orgs() returns uuid[]
language sql stable security definer set search_path = public, pg_temp
as $$
  select coalesce(array_agg(distinct c.org_id), '{}'::uuid[])
  from (
    select m.org_id from organization_memberships m where m.user_id = app.current_user_id()
    union all
    select s.org_id from staff_assignments s where s.user_id = app.current_user_id()
    union all
    select o.id from organizations o where app.is_agency_admin()
  ) c
  where app.can_access_org(c.org_id)
$$;
revoke all on function app.accessible_orgs() from public;
grant execute on function app.accessible_orgs() to iaq_app_user;

do $$
declare
  r record;
  q text;
begin
  for r in
    select schemaname, tablename, policyname, qual from pg_policies
    where schemaname = 'public' and cmd = 'SELECT' and qual ~ 'app\.(has_permission|can_view_conversation|can_access_org)\('
  loop
    q := r.qual;
    q := regexp_replace(q, 'app\.can_view_conversation\((([a-z_]+\.)?)org_id, (([a-z_]+\.)?)owner_user_id, (([a-z_]+\.)?)assigned_user_id\)',
      '((\1org_id = ANY ((SELECT app.permitted_orgs(''inbox.view''::text))::uuid[])) AND ((\1org_id = ANY ((SELECT app.permitted_orgs(''inbox.view_all''::text))::uuid[])) OR (\3owner_user_id = (SELECT app.current_user_id())) OR (\5assigned_user_id = (SELECT app.current_user_id()))))', 'g');
    q := regexp_replace(q, 'app\.has_permission\((([a-z_]+\.)?)org_id, (''[a-z_.]+''::text)\)', '(\1org_id = ANY ((SELECT app.permitted_orgs(\3))::uuid[]))', 'g');
    q := regexp_replace(q, 'app\.can_access_org\((([a-z_]+\.)?)org_id\)', '(\1org_id = ANY ((SELECT app.accessible_orgs())::uuid[]))', 'g');
    if q <> r.qual then
      execute format('alter policy %I on %I.%I using (%s)', r.policyname, r.schemaname, r.tablename, q);
    end if;
  end loop;
end
$$;
